package com.mavric.health.organization.application;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.*;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real service/store/templates with offline executor and modeled manager, no HTTP or SQL connection. */
class OrganizationServiceSqlServerTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final IdentityService identity=mock(IdentityService.class);final OrganizationService service=new OrganizationService(access,new SqlServerOrganizationStore(executor,manager),identity);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/organization");
 OrganizationServiceSqlServerTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(TENANT,c.tenantId());assertEquals(ID,c.actorId());return new SqlServerExecutor.Result(List.of(List.of()),List.of());});}
 void actor(String role,boolean platform){var a=new Actor(ID,"Synthetic","qa@example.test",platform?null:TENANT,List.of(role),"a".repeat(64));doReturn(a).when(access).actor();var t=new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("CORE"));if(platform)request.removeAttribute("health.tenant");else request.setAttribute("health.tenant",t);request.setAttribute("health.actor",a);doReturn(t).when(access).tenant();TraceContext.REQUEST.set(request);}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void admFiveReadsUseRealStoreAndOnlyTypedSp(){actor("ADM",false);request.addHeader("X-Roles","SAD");request.addHeader("X-Tenant-Id","forged");request.setContent("forged body".getBytes());assertEquals(List.of(),service.lookup(" QA@EXAMPLE.TEST "));assertEquals(List.of(),service.directory());assertEquals(List.of(),service.professionals(null));assertEquals(List.of(),service.catalog());assertEquals(List.of(),service.availablePlans());verify(executor).execute(eq(SqlServerProcedure.ORGANIZATION_LOOKUP),any(),eq(" qa@example.test "));verify(executor).execute(eq(SqlServerProcedure.ORGANIZATION_DIRECTORY),any(),any(Object[].class));verify(executor).execute(eq(SqlServerProcedure.ORGANIZATION_PROFESSIONALS),any(),isNull());verify(executor).execute(eq(SqlServerProcedure.ORGANIZATION_CATALOG),any(),any(Object[].class));verify(executor).execute(eq(SqlServerProcedure.ORGANIZATION_PLANS),any(),any(Object[].class));verify(access,times(2)).roles("ADM");verify(access,times(5)).tenant();verify(access,never()).branch(any());verifyNoInteractions(sql,identity);}
 @Test void ordinaryTenantRolesReadDirectoryProfessionalsCatalogButNotAdminLookupPlans(){for(String role:List.of("PRO","PAC","RES","AUD","REC")){actor(role,false);assertEquals(403,assertThrows(ApiException.class,()->service.lookup("x")).status);assertEquals(403,assertThrows(ApiException.class,service::availablePlans).status);assertTrue(service.directory().isEmpty());assertTrue(service.professionals(null).isEmpty());assertTrue(service.catalog().isEmpty());}verify(executor,times(15)).execute(any(),any(),any(Object[].class));verify(access,never()).roles(any(String[].class));verifyNoInteractions(sql,identity);}
 @Test void professionalsValidatesUuidBeforeBranchAndBranchDenialPreventsSp(){actor("ADM",false);assertEquals(400,assertThrows(ApiException.class,()->service.professionals("bad")).status);verify(access,never()).branch(anyString());verifyNoInteractions(executor);doAnswer(inv->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());return null;}).when(access).branch(ID);service.professionals(ID);var order=inOrder(access,executor);order.verify(access).branch(ID);order.verify(executor).execute(eq(SqlServerProcedure.ORGANIZATION_PROFESSIONALS),any(),eq(ID));for(int status:List.of(403,404)){doThrow(new ApiException(status,"SAFE","Safe")).when(access).branch(ID);assertEquals(status,assertThrows(ApiException.class,()->service.professionals(ID)).status);}verify(access,times(3)).branch(ID);verify(executor,times(1)).execute(any(),any(),any(Object[].class));}
 @Test void requestMissingActorPlatformMismatchAndMalformedHostFailBeforeSp(){assertEquals(500,assertThrows(ApiException.class,service::directory).status);actor("ADM",false);doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,service::directory).status);actor("SAD",true);assertEquals(403,assertThrows(ApiException.class,service::directory).status);actor("ADM",false);request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,service::catalog).status);actor("ADM",false);request.setAttribute("health.tenant",new TenantRef(ID,"Other","other","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals(403,assertThrows(ApiException.class,service::directory).status);request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,service::directory).status);verifyNoInteractions(executor,sql,identity);}
 @Test void sixUnconvertedMethodsGuardBeforeAnyCollaboratorOrInputs(){for(Runnable work:List.<Runnable>of(()->service.configuration(null),()->service.subscription(null,null),()->service.branch(null,null,null),()->service.area(null,null,null),()->service.specialties(null,null),()->service.member(null,null))){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);}verifyNoInteractions(access,identity,sql,executor);}
 @Test void safeSpErrorsNeverFallBack(){actor("ADM",false);doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51001))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,service::catalog);assertEquals(403,e.status);assertFalse(e.toString().contains("private"));verify(executor,times(1)).execute(any(),any(),any(Object[].class));verifyNoInteractions(sql,identity);}
 @Test void minimalSpringChoosesLegacyAndLegacyReadsNeverUseStore(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(access.tenant()).thenReturn(new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));try(var c=new AnnotationConfigApplicationContext()){c.registerBean(Sql.class,()->sql);c.registerBean(Access.class,()->access);c.registerBean(IdentityService.class,()->identity);c.registerBean(OrganizationService.class);c.refresh();var legacy=c.getBean(OrganizationService.class);assertTrue(legacy.lookup("QA@EXAMPLE.TEST").isEmpty());assertTrue(legacy.directory().isEmpty());assertTrue(legacy.professionals(null).isEmpty());assertTrue(legacy.catalog().isEmpty());assertTrue(legacy.availablePlans().isEmpty());verify(sql,times(5)).rows(anyString(),any(Object[].class));assertEquals(0,c.getBeanNamesForType(javax.sql.DataSource.class).length);assertEquals(0,c.getBeanNamesForType(SqlServerOrganizationStore.class).length);}verifyNoInteractions(executor,identity);}
}
